// ── Protocol types (generated by ts-rs from Rust source) ─────────────

import type {
  ImageAttachment as _ImageAttachment,
  SessionSummary as _SessionSummary,
} from "./generated/protocol";
export type {
  ClientMessage,
  ServerMessage,
  ImageAttachment,
  SessionCategory,
  SessionCommandErrorCode,
  SessionDeliveryOutcome,
  SessionListResponse,
  SessionRunStatus,
  SessionState,
  SessionSummary,
  WorkbenchInfo,
  WorkbenchRelayOrigins,
  ArtifactSummary,
} from "./generated/protocol";

// Local aliases for use within this file
type ImageAttachment = _ImageAttachment;
type SessionSummary = _SessionSummary;

// ── Chat history ─────────────────────────────────────────────────────

export interface ToolCallRecord {
  id: string;
  name: string;
  /**
   * Deliberately `unknown`: the wire shape depends on the source. History
   * (`/api/chat/history`) serializes this from a Rust `serde_json::Value`, so
   * it arrives as an **object**; other paths have carried it as a JSON
   * **string**. Typing it as `string` previously invited a bare
   * `JSON.parse(...)`, which throws `SyntaxError` on an object and took out
   * the whole feed render.
   *
   * Keep this `unknown` so the compiler forces every reader through
   * `normalizeToolArgs()` instead of assuming a shape.
   */
  arguments: unknown;
}

/** Person behind a user message that arrived on a chat interface. */
export interface MessageSender {
  name: string;
  id: string;
  interface: string;
  location?: string;
}

export interface RecentMessage {
  role: "user" | "assistant" | "tool" | "system";
  content: string;
  tool_calls?: ToolCallRecord[];
  tool_call_id?: string;
  timestamp: string;
  visibility: "user" | "background";
  sender?: MessageSender;
  /** The agent that sent this message, for one agent's message to another. */
  agent_sender?: AgentSender;
}

/** The agent behind a message one agent sent another. */
export interface AgentSender {
  /** Sender's address (`main` or a session address). */
  address: string;
  /** Sender's category label (`main`, `scheduled`, `external`, `spawned`). */
  category: string;
}

// ── Agent sessions ───────────────────────────────────────────────────

/** `GET /api/sessions/runs/{run_id}/transcript` response. */
export interface SessionTranscriptResponse {
  session: SessionSummary;
  messages: RecentMessage[];
}

// ── Chat history segments (paginated lazy-load) ──────────────────────

export interface RecentHistorySegment {
  kind: "recent";
  messages: RecentMessage[];
  next_cursor: string | null;
}

export interface EpisodeHistorySegment {
  kind: "episode";
  episode_id: string;
  date: string; // YYYY-MM-DD
  messages: RecentMessage[];
  next_cursor: string | null;
}

export type ChatHistorySegment = RecentHistorySegment | EpisodeHistorySegment;

