// ── Feed items (UI rendering) ────────────────────────────────────────

export type ConnectionStatus = "connecting" | "connected" | "disconnected";

export interface ToolCallState {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  status: "running" | "done" | "error";
  result?: string;
}

interface FeedItemBase {
  id: number;
}

export interface UserFeedItem extends FeedItemBase {
  kind: "user";
  content: string;
  images?: ImageAttachment[];
  sender?: MessageSender;
}

export interface AssistantFeedItem extends FeedItemBase {
  kind: "assistant";
  content: string;
}

export interface DividerFeedItem extends FeedItemBase {
  kind: "divider";
  label: string;
  variant?: "episode" | "day";
}

export interface CompressedMarkerFeedItem extends FeedItemBase {
  kind: "compressed-marker";
}

export interface ToolGroupFeedItem extends FeedItemBase {
  kind: "tool-group";
  calls: ToolCallState[];
}

export interface FileAttachmentFeedItem extends FeedItemBase {
  kind: "file-attachment";
  filename: string;
  mimeType: string;
  size: number;
  url: string;
  caption: string | null;
}

/**
 * Client-originated, ephemeral system text rendered inline in the chat
 * stream. Used for slash command output (`/help`, `/status`, `/context`)
 * that the user wants to read carefully but should not persist across
 * reloads or land in conversation history.
 */
export interface LocalSystemFeedItem extends FeedItemBase {
  kind: "local-system";
  content: string;
}

/**
 * A message one agent sent another: a session's result relayed to the main
 * agent (or any `message_agent` call to it), or, inside a session's
 * transcript, a message from another agent. Rendered as a compact item that
 * links to the sending session.
 */
export interface AgentMessageFeedItem extends FeedItemBase {
  kind: "agent-message";
  /** Sender's address (`main` or a session address). */
  from: string;
  /** Sender's category label, when known. */
  category: string | null;
  content: string;
  /** Sending run, when known (live frames carry it; history doesn't). */
  runId: string | null;
}

/**
 * A one-line status note inside a session view: delivery outcomes, command
 * failures, session errors, and the run finishing.
 */
export interface StatusFeedItem extends FeedItemBase {
  kind: "status";
  tone: "info" | "error";
  content: string;
}

export type FeedItem =
  | AgentMessageFeedItem
  | StatusFeedItem
  | UserFeedItem
  | AssistantFeedItem
  | DividerFeedItem
  | CompressedMarkerFeedItem
  | ToolGroupFeedItem
  | FileAttachmentFeedItem
  | LocalSystemFeedItem;

// ── User Inbox ───────────────────────────────────────────────────────

// Field names match the JSON wire format as-is (snake_case), consistent with
// the rest of UserInboxItem below — this endpoint doesn't go through the
// camelCase mapping step that ServerMessage-derived feed items do.
export interface UserInboxAttachment {
  filename: string;
  mime_type: string;
  size: number;
  url: string;
}

export interface UserInboxItem {
  id: string;
  title: string;
  body: string;
  source: string;
  timestamp: string;
  read: boolean;
  attachments: UserInboxAttachment[];
}
